def stats(values):
    values = np.asarray(values, float)
    return (float(values.mean()), float(values.std(ddof=1) / np.sqrt(len(values))))

def run_case(cfg):
    sigmas = np.asarray(cfg['sigmas'], float)
    p = float(cfg['p'])
    if cfg['c_mode'] == 'common':
        c = 12 * np.sqrt(3.0)
        policies = ['vucb']
    else:
        c = sigmas if cfg['c_mode'] == 'true' else np.full(len(sigmas), sigmas.max())
        policies = ['uniform', 'etc', 'vucb']
        if 'profiles' in cfg['studies']:
            policies.append('integer_oracle')
        if cfg['family'] != 'exponential' and np.isinf(p):
            policies.append('bas')
    return run_experiment(sigmas, cfg['T'], p, cfg['family'], policies, cfg['M'], cfg['seed'], c, cfg['alpha'], cfg['ucb_kind'])

def summarize(cfg, results):
    rows = []
    shares = []
    for (policy, result) in results.items():
        (mean, se) = stats(result['regret'])
        row = {k: cfg[k] for k in ('id', 'family', 'p', 'profile', 'T', 'M', 'seed')}
        row.update(G=len(cfg['sigmas']), policy=policy, regret=mean, mcse=se, ci_lo=mean - 1.959963984540054 * se, ci_hi=mean + 1.959963984540054 * se)
        for study in cfg['studies']:
            rows.append(dict(row, study=study))
        if 'norm' in cfg['studies']:
            oracle = oracle_proportions(cfg['sigmas'], float(cfg['p']))
            for (g, sigma) in enumerate(cfg['sigmas']):
                (mean, se) = stats(result['counts'][:, g] / cfg['T'])
                shares.append(dict(p=cfg['p'], group=g + 1, sigma=sigma, mean_share=mean, mcse=se, oracle_share=float(oracle[g])))
    return (rows, shares)

def write_csv(path, rows):
    if rows:
        with path.open('w', newline='') as stream:
            writer = csv.DictWriter(stream, fieldnames=list(rows[0]))
            writer.writeheader()
            writer.writerows(rows)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--study', choices=['all', 'budget', 'profiles', 'groups', 'norm'], default='all')
    parser.add_argument('--output', type=Path, default=Path(__file__).parent / 'results' / 'section7')
    args = parser.parse_args()
    args.output.mkdir(parents=True, exist_ok=True)
    selected = [c for c in CASES if args.study == 'all' or args.study in c['studies']]
    (rows, shares) = ([], [])
    for cfg in selected:
        path = args.output / (cfg['id'] + '.json')
        raw = path.with_suffix('.npz')
        if path.exists() and raw.exists():
            record = json.loads(path.read_text())
            if record['configuration'] != cfg:
                raise ValueError('Saved configuration differs: ' + cfg['id'])
        else:
            results = run_case(cfg)
            (result_rows, result_shares) = summarize(cfg, results)
            arrays = {policy + '__' + key: value for (policy, result) in results.items() for (key, value) in result.items()}
            np.savez_compressed(raw, **arrays)
            record = dict(configuration=cfg, summary=result_rows, shares=result_shares)
            path.write_text(json.dumps(record, indent=2, allow_nan=False) + '\n')
        rows.extend(record['summary'])
        shares.extend(record['shares'])
        print(cfg['id'], flush=True)
    write_csv(args.output / ('summary-' + args.study + '.csv'), rows)
    write_csv(args.output / ('shares-' + args.study + '.csv'), shares)
if __name__ == '__main__':
    main()
